DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE `audit_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `entity_type` varchar(80) NOT NULL,
  `entity_id` varchar(80) DEFAULT NULL,
  `action` varchar(40) NOT NULL,
  `before_json` longtext DEFAULT NULL,
  `after_json` longtext DEFAULT NULL,
  `changed_fields` text DEFAULT NULL,
  `performed_by_user_id` int(11) unsigned DEFAULT NULL,
  `performed_by_username` varchar(120) DEFAULT NULL,
  `performed_by_branch` varchar(120) DEFAULT NULL,
  `request_ip` varchar(64) DEFAULT NULL,
  `request_user_agent` varchar(255) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `entity_type_entity_id` (`entity_type`,`entity_id`),
  KEY `performed_by_user_id_created_at` (`performed_by_user_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `banks`;
CREATE TABLE `banks` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  `country` varchar(80) DEFAULT NULL,
  `country_bank_code` varchar(20) DEFAULT NULL,
  `category` varchar(40) DEFAULT NULL,
  `bank_code` varchar(50) DEFAULT NULL,
  `swift_code` varchar(50) DEFAULT NULL,
  `sender_bank` tinyint(1) DEFAULT 0,
  `receiver_bank` tinyint(1) DEFAULT 1,
  `pickup_bank` tinyint(1) DEFAULT 0,
  `status` varchar(20) NOT NULL DEFAULT 'active',
  `is_default` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `beneficiaries`;
CREATE TABLE `beneficiaries` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) unsigned NOT NULL,
  `name` varchar(255) NOT NULL,
  `country` varchar(100) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `city` varchar(120) DEFAULT NULL,
  `date_of_birth` varchar(20) DEFAULT NULL,
  `place_of_birth` varchar(120) DEFAULT NULL,
  `bank_name` varchar(255) NOT NULL,
  `branch_name` varchar(255) DEFAULT NULL,
  `account_number` varchar(80) DEFAULT NULL,
  `payment_mode` varchar(120) DEFAULT NULL,
  `iban` varchar(60) DEFAULT NULL,
  `branch_code` varchar(60) DEFAULT NULL,
  `receiver_id_type` varchar(60) DEFAULT NULL,
  `receiver_id_number` varchar(100) DEFAULT NULL,
  `relation` varchar(100) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `mobile_number` varchar(50) DEFAULT NULL,
  `status` enum('active','inactive') DEFAULT 'active',
  `aml_status` enum('pending','clear','review','hit') DEFAULT 'pending',
  `aml_hits` int(11) DEFAULT NULL,
  `aml_checked_at` datetime DEFAULT NULL,
  `aml_reference` varchar(120) DEFAULT NULL,
  `veriff_session_id` varchar(120) DEFAULT NULL,
  `veriff_pep_sanction_match` text DEFAULT NULL,
  `veriff_status` varchar(80) DEFAULT 'pending',
  `veriff_checked_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `beneficiaries_customer_id_foreign` (`customer_id`),
  CONSTRAINT `beneficiaries_customer_id_foreign` FOREIGN KEY (`customer_id`) REFERENCES `remitters` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `branch_access_requests`;
CREATE TABLE `branch_access_requests` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `remitter_id` int(10) unsigned NOT NULL,
  `sender_id` varchar(64) DEFAULT NULL,
  `sender_name` varchar(255) DEFAULT NULL,
  `origin_branch_code` varchar(120) NOT NULL,
  `origin_branch_name` varchar(255) DEFAULT NULL,
  `requested_branch_code` varchar(120) NOT NULL,
  `requested_branch_name` varchar(255) DEFAULT NULL,
  `requested_by_user_id` int(10) unsigned DEFAULT NULL,
  `requested_by_username` varchar(120) DEFAULT NULL,
  `status` enum('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  `reviewed_by_user_id` int(10) unsigned DEFAULT NULL,
  `reviewed_by_username` varchar(120) DEFAULT NULL,
