  `note` text DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_remitter_branch_status` (`remitter_id`,`origin_branch_code`,`requested_branch_code`,`status`),
  KEY `remitter_id_status` (`remitter_id`,`status`),
  KEY `origin_branch_code_status` (`origin_branch_code`,`status`),
  KEY `requested_branch_code_status` (`requested_branch_code`,`status`),
  CONSTRAINT `branch_access_requests_remitter_id_foreign` FOREIGN KEY (`remitter_id`) REFERENCES `remitters` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `branch_currency_rates`;
