  `status` varchar(20) NOT NULL DEFAULT 'open',
  `priority` varchar(20) NOT NULL DEFAULT 'normal',
  `last_message_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `transaction_settings`;
CREATE TABLE `transaction_settings` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `channel` varchar(20) NOT NULL DEFAULT 'backend',
  `period` varchar(20) NOT NULL DEFAULT 'month',
  `currency` varchar(10) NOT NULL DEFAULT 'GBP',
  `limit_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `active` varchar(3) NOT NULL DEFAULT 'yes',
  `updated_by` varchar(100) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `channel_period_currency` (`channel`,`period`,`currency`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `transaction_user_limits`;
CREATE TABLE `transaction_user_limits` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `user_email` varchar(190) NOT NULL,
  `channel` varchar(20) NOT NULL DEFAULT 'app',
  `period` varchar(20) NOT NULL DEFAULT 'month',
  `currency` varchar(10) NOT NULL DEFAULT 'GBP',
  `limit_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `active` varchar(3) NOT NULL DEFAULT 'yes',
  `updated_by` varchar(100) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_email_channel_period_currency` (`user_email`,`channel`,`period`,`currency`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `transfers`;
CREATE TABLE `transfers` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(50) DEFAULT NULL,
  `remitter_id` int(11) unsigned NOT NULL,
  `branch_id` varchar(100) DEFAULT NULL,
  `created_by` int(11) unsigned DEFAULT NULL,
  `beneficiary_id` int(11) unsigned DEFAULT NULL,
  `source_amount` decimal(10,2) NOT NULL,
  `dest_amount` decimal(10,2) NOT NULL,
  `rate` decimal(10,4) NOT NULL,
  `payment_mode` varchar(50) NOT NULL,
  `source_of_funds` varchar(100) NOT NULL,
  `purpose` varchar(255) NOT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'pending',
  `type` enum('branch','online','mobile','agent') DEFAULT 'branch',
  `collection_method` enum('cash','bank_transfer','card') DEFAULT 'cash',
  `meta_json` longtext DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `transfers_remitter_id_foreign` (`remitter_id`),
  KEY `transfers_beneficiary_id_foreign` (`beneficiary_id`),
  CONSTRAINT `transfers_beneficiary_id_foreign` FOREIGN KEY (`beneficiary_id`) REFERENCES `beneficiaries` (`id`) ON DELETE CASCADE ON UPDATE SET NULL,
  CONSTRAINT `transfers_remitter_id_foreign` FOREIGN KEY (`remitter_id`) REFERENCES `remitters` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `user_logs`;
CREATE TABLE `user_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) unsigned DEFAULT NULL,
  `username` varchar(100) DEFAULT NULL,
  `transfers_impact` int(11) NOT NULL DEFAULT 0,
  `transfers_approve_impact` int(11) NOT NULL DEFAULT 0,
  `log_country` varchar(100) DEFAULT NULL,
  `log_ip` varchar(64) DEFAULT NULL,
  `sign_in` datetime DEFAULT NULL,
  `sign_off` datetime DEFAULT NULL,
  `sign_off_note` text DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `username` varchar(100) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `email` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `role` varchar(50) NOT NULL DEFAULT 'admin',
  `role_id` int(11) unsigned DEFAULT NULL,
  `branch_id` varchar(100) DEFAULT NULL,
  `status` enum('active','inactive','suspended') NOT NULL DEFAULT 'active',
  `system_defined` enum('yes','no') DEFAULT 'no',
  `twofa_status` enum('active','inactive') DEFAULT 'active',
  `twofa_qr_code` varchar(255) DEFAULT NULL,
  `signature` varchar(255) DEFAULT NULL,
  `profile_photo` varchar(255) DEFAULT NULL,
  `branch` varchar(100) DEFAULT NULL,
  `last_login` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `updated_by` varchar(100) DEFAULT NULL,
  `permissions` text DEFAULT NULL COMMENT 'JSON encoded permissions array',
  `verification_token` varchar(255) DEFAULT NULL,
  `email_verified_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  KEY `fk_users_role_id` (`role_id`),
  CONSTRAINT `fk_users_role_id` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


COMMIT;
